#include <string.h>
#include <stdio.h>
#include <stdlib.h>
#include <sys/socket.h>
#include <netinet/in.h>

#define REQUIRED_LENGTH 5
#define MAX_PACKET_ID 1000

int handle_packet(int s, unsigned char* data, int len, struct sockaddr_in* s_in) {
    if (s < 0 || data == NULL || len < 0 || s_in == NULL) {
        return 1;
    }

    if (len < 0 || len > INT_MAX) {
        return 1;
    }

    if (len == REQUIRED_LENGTH && memcmp(data, "sorbo", 5) == 0) {
        const char* response = "internet check\n";
        if (sendto(s, response, strlen(response), 0, (struct sockaddr*)s_in, sizeof(*s_in)) < 0) {
            return 1;
        }
        return 0;
    }

    if (len < 8) {
        return 1;
    }

    int packet_id = 0;
    memcpy(&packet_id, data, sizeof(packet_id));
    int packet_len = 0;
    memcpy(&packet_len, data + 4, sizeof(packet_len));

    if (packet_len < 0 || packet_len > len - 8) {
        return 1;
    }

    static int last_packet_id = -1;
    if (packet_id == last_packet_id) {
        return 0;
    }

    last_packet_id = packet_id;

    if (packet_id >= MAX_PACKET_ID) {
        last_packet_id = 0;
    }

    if (sendto(s, data + 8, packet_len, 0, (struct sockaddr*)s_in, sizeof(*s_in)) < 0) {
        return 1;
    }

    return 0;
}
